mapper.select:
SELECT

FROM aide_user

    del_flag = 0

        AND username LIKE CONCAT('%', #{user.username}, '%')


        AND mobile = #{user.mobile}


        AND email = #{user.email}


        AND status = #{user.status}


        AND role = #{user.role}


        AND sex = #{user.sex}


        AND create_time >= #{startTime}


        AND create_time <= #{endTime}


ORDER BY create_time DESC

